const DICTS = { uz, en, ru };
let cyrl = null;
function dict(lang) {
  if (lang === "uz-cyrl") {
    if (!cyrl) cyrl = { ...Object.fromEntries(Object.entries(uz).map(([k, v]) => [k, toCyrillic(v)])), ...uzCyrl };
    return cyrl;
  }
  return DICTS[lang] ?? uz;
}

export function makeT(lang) {
  const d = dict(lang);
  return (key, vars, fallback) => {
    let s = d[key] ?? en[key] ?? uz[key] ?? fallback ?? key;
    if (vars) s = s.replace(/\{(\w+)\}/g, (_, v) => (vars[v] ?? ""));
    return s;
  };
}

/** Birinchi ishga tushishda: ingliz tili (sayt bilan bir xil standart). Onboarding va Sozlamalarda almashtiriladi. */
export function detectLang() {
  return "en";
}

export function relTime(ts, t) {
  if (!ts) return "";
  const s = Math.max(0, (Date.now() - ts) / 1000);
  if (s < 60) return t("time.now");
  if (s < 3600) return t("time.min", { n: Math.round(s / 60) });
  if (s < 86400) return t("time.hour", { n: Math.round(s / 3600) });
  return t("time.day", { n: Math.round(s / 86400) });
}

export const I18n = createContext(makeT("en"));
export const useT = () => useContext(I18n);
export const KEYS = { uz, en, ru };
/** Qo'lda tekshirilgan kirill (qolganlari translit) — i18n:check uchun. */
export const UZ_CYRL = uzCyrl;
